use crate::{test034 as t,catalog,model::*,rules::*,unit_support::*};
#[test]
fn test034_pinned_test_blue_metadata_closed_and_exact_definition(){let c=catalog::card(t::ID);assert_eq!((c.cost,c.color.as_str(),c.magic.as_str(),c.unique,c.supported),(1,"蓝","心灵",false,false));assert_eq!(c.loyalty,["蓝色"]);assert_eq!(c.subtypes,["状态","超能力"]);assert!(c.keywords.iter().any(|k|k=="非资产"));let d=t::definition();assert_eq!(d.abilities.len(),2);for n in 0..3{let mut bad=d.clone();match n{0=>bad.attachment.as_mut().unwrap().host.subtype=None,1=>bad.attachment.as_mut().unwrap().host_icons.investigation=2,_=>bad.abilities[1].costs.clear()};assert!(t::validate_definition(t::ID,&bad).is_err());}}
fn attach(g:&Game,source:&str,host:&str)->Action{Action{card_id:Some(source.into()),target_id:Some(host.into()),..Action::new("play")}}
fn hand(source:&str)->Action{Action{card_id:Some(source.into()),ability_id:Some(crate::import20_contest::TEST034_HAND.into()),..Action::new("activate")}}
#[test]
fn test034_actual_attach_any_vampire_permanent_icon_and_nonasset(){for seat in 0..4{let mut g=game();let host=field(&mut g,"JC029",seat);fund(&mut g,0,"JC029",2);let id=held(&mut g,t::ID,0);reject(&mut g,0,Action{card_id:Some(id.clone()),..Action::new("asset")});let human=field(&mut g,"JC125",0);let bad=attach(&g,&id,&human);reject(&mut g,0,bad);let before=g.current_icons(g.board(&host).unwrap().1,0).investigation;let a=attach(&g,&id,&host);act(&mut g,0,a);top(&mut g);assert_eq!(g.resources(0),1);assert_eq!(g.current_icons(g.board(&host).unwrap().1,0).investigation,before+1);assert!(g.attachments.iter().any(|a|a.card.definition==t::ID&&a.host_id==host));g.first_team=1-g.first_team;assert_eq!(g.current_icons(g.board(&host).unwrap().1,0).investigation,1);restore(&mut g);}}
#[test]
fn test034_response_hidden_host_fizzles_without_refund(){let mut g=game();let host=field(&mut g,"JC029",2);fund(&mut g,0,"JC029",1);let id=held(&mut g,t::ID,0);let a=attach(&g,&id,&host);act(&mut g,0,a);g.hide_in_place_successor(&host).unwrap();restore(&mut g);top(&mut g);assert!(g.attachments.iter().all(|a|a.card.definition!=t::ID));assert!(g.players[0].graveyard.iter().any(|c|c.definition==t::ID));assert_eq!(g.resources(0),0);restore(&mut g);}
#[test]
fn test034_hand_action_cost_two_discard_self_and_not_printed_loyalty(){let mut g=game();fund(&mut g,0,"JC125",1);let id=held(&mut g,t::ID,0);reject(&mut g,0,hand(&id));fund(&mut g,0,"JC125",1);let mut bad=hand(&id);bad.target_id=Some("society:p0".into());reject(&mut g,0,bad);for seat in 0..4{held(&mut g,"JC125",seat);deck_cards(&mut g,seat,&["JC125";4]);}act(&mut g,0,hand(&id));assert_eq!(g.resources(0),0);assert!(!g.players[0].hand.iter().any(|c|c.id==id));assert!(g.players[0].graveyard.iter().any(|c|c.definition==t::ID));top(&mut g);for _ in 0..64{if g.pending.is_some(){resolve_choice(&mut g);}else if !g.stack.is_empty(){pass(&mut g);}else{break;}}assert_eq!(g.mystic_history.len(),1);assert!(g.mystic_contest.is_none());reject(&mut g,0,hand(&id));restore(&mut g);}
#[test]
fn test034_corrupt_attachment_transaction_and_hand_receipt_reject(){for use_hand in [false,true]{let mut g=game();let host=field(&mut g,"JC029",0);fund(&mut g,0,"JC029",2);let id=held(&mut g,t::ID,0);let a=if use_hand{hand(&id)}else{attach(&g,&id,&host)};act(&mut g,0,a);for case in 0..3{let mut bad=g.clone();let f=bad.stack.last_mut().unwrap().frame.as_mut().unwrap();match case{0=>f.already_paid.clear(),1=>f.source.card.definition="JC001".into(),_=>if use_hand{f.steps[0].op=Op::MysticContest{actor_bonus:4};}else{f.targets[0].spec.subtype=None;}}assert!(Game::from_persisted(&serde_json::to_string(&bad).unwrap()).is_err());let mut room=crate::jc029_tests::envelope(&g);room.game=bad;assert!(crate::room::RoomEnvelope::from_persisted(&serde_json::to_string(&room).unwrap()).is_err());}}}
fn constructed(seed:u64,attach_path:bool)->(Game,crate::deck::DeckDraft){let mut d=crate::deck::preset("watchers").unwrap();d.id="closed-test034".into();d.name="兽性直觉固定TEST图版".into();d.description="非官方预组，仅私有候选测试".into();d.society_id=None;d.cards=vec![catalog::DeckEntry{card_id:"JC125".into(),count:if attach_path{41}else{47}},catalog::DeckEntry{card_id:t::ID.into(),count:3}];if attach_path{d.cards.extend([catalog::DeckEntry{card_id:"JC029".into(),count:3},catalog::DeckEntry{card_id:"JC030".into(),count:3}]);}assert!(crate::deck::validate(d.clone()).is_err());let mut cards=catalog::catalog().cards.clone();cards.iter_mut().find(|c|c.id==t::ID).unwrap().supported=true;let d=crate::deck::validate_with_registry(d,&cards,&catalog::catalog().societies).unwrap();let mut other=d.clone();other.cards=vec![catalog::DeckEntry{card_id:"JC125".into(),count:50}];let other=crate::deck::validate(other).unwrap();let mut g=Game::new("test034-natural".into(),"LOCAL".into(),"teams".into(),"P0".into(),"watchers".into(),seed).unwrap();for s in 1..4{g.join(format!("P{s}"),"watchers".into()).unwrap();}g.start_validated_decks(vec![d.clone(),other.clone(),other.clone(),other]).unwrap();g.drive().unwrap();(g,d)}
fn natural(attach_path:bool,index:usize)->serde_json::Value{use crate::abi112_review_play_tests::Trace;let(seed,g,d)=(1..513).find_map(|seed|{let(g,d)=constructed(seed,attach_path);let h=&g.players[0].hand;let has=|id:&str|h.iter().any(|c|c.definition==id);(has(t::ID)&&(!attach_path||has("JC029")&&h.iter().filter(|c|c.definition=="JC030").count()>=2)).then_some((seed,g,d))}).expect("bounded actual initial hand");let name=if attach_path{"test034-natural-attach-vampire"}else{"test034-natural-hand-contest"};let mut trace=Trace::new_preserving_rng(g,name.into(),index);let mut activated=false;let mut done=false;
 for _ in 0..640{if let Some(p)=trace.room.game.pending.clone(){let ids=p.choice.options.iter().take(p.choice.min.unwrap_or(0)).map(|o|o.id.clone()).collect();trace.choose(ids);continue;}let g=&trace.room.game;if attach_path&&g.attachments.iter().any(|a|a.card.definition==t::ID){let a=g.attachments.iter().find(|a|a.card.definition==t::ID).unwrap();assert_eq!(g.current_icons(g.board(&a.host_id).unwrap().1,g.board(&a.host_id).unwrap().0).investigation,1);done=true;break;}if !attach_path&&activated&&g.stack.is_empty()&&g.mystic_contest.is_none()&&!g.mystic_history.is_empty(){done=true;break;}let legal=g.legal_actions(0);let card_def=|id:Option<&String>,definition:&str|id.is_some_and(|id|g.players[0].hand.iter().any(|c|&c.id==id&&c.definition==definition));let a=if g.players[0].assets.is_empty(){legal.iter().find(|a|a.action.kind=="asset"&&card_def(a.action.card_id.as_ref(),if attach_path{"JC030"}else{"JC125"}))}else if g.players[0].assets.len()<2{legal.iter().find(|a|a.action.kind=="asset"&&card_def(a.action.card_id.as_ref(),if attach_path{"JC030"}else{"JC125"}))}else if attach_path&&!g.regions.iter().any(|r|r.cards.iter().any(|c|c.definition=="JC029"&&c.controller==0&&!c.face_down)){legal.iter().find(|a|a.action.kind=="deploy"&&a.action.region==Some(0)&&card_def(a.action.card_id.as_ref(),"JC029"))}else if attach_path{legal.iter().find(|a|a.action.kind=="play"&&card_def(a.action.card_id.as_ref(),t::ID))}else{legal.iter().find(|a|a.action.ability_id.as_deref()==Some(crate::import20_contest::TEST034_HAND))};if let Some(a)=a{if a.action.ability_id.as_deref()==Some(crate::import20_contest::TEST034_HAND){activated=true;}trace.action(0,a.action.clone());}else{trace.pass();}}
 assert!(done,"{} at turn {}",name,trace.room.game.turn);let mut v=trace.value();v["construction"]=serde_json::json!({"deck":d,"seed":seed,"admission":"private TEST034 registry only; formal print eligibility unconfirmed","noLayoutOrResourceMutation":true});for step in v["steps"].as_array_mut().unwrap(){let r=crate::room::RoomEnvelope::from_persisted(step["expected"]["state"].as_str().unwrap()).unwrap();let cmd=serde_json::from_value(step["command"].clone()).unwrap();let duplicate=r.transition(step["seat"].as_u64().unwrap()as usize,Some(cmd),0).unwrap();assert_eq!(duplicate.outcome,"rejected");assert_eq!(duplicate.state,step["expected"]["state"]);assert!(!duplicate.changed&&duplicate.journal.is_empty());step["duplicate"]=serde_json::to_value(duplicate).unwrap();}v}
#[test]
fn test034_natural_construction_two_real_paths_export(){let cases=vec![natural(true,660),natural(false,661)];if let Ok(path)=std::env::var("TEST034_NATIVE_OUT"){std::fs::write(path,serde_json::to_vec_pretty(&serde_json::json!({"catalog":catalog::catalog(),"sourceBindings":source_bindings(),"cases":cases})).unwrap()).unwrap();}}
fn source_bindings()->serde_json::Value{use sha2::{Digest,Sha256};let mut b=crate::jc066_tests::source_bindings();for(n,bytes)in[("rust-game/src/test034.rs",include_bytes!("test034.rs").as_slice()),("rust-game/src/test034_tests.rs",include_bytes!("test034_tests.rs").as_slice()),("rust-game/src/import20_contest.rs",include_bytes!("import20_contest.rs").as_slice()),("rust-game/src/pack_a_contest.rs",include_bytes!("pack_a_contest.rs").as_slice())]{b["files"].as_object_mut().unwrap().insert(n.into(),serde_json::json!(format!("{:x}",Sha256::digest(bytes))));}b}
